SELECT "t3"."order_number", "t3"."invoice_id", "t3"."due", "t3"."open_amount", 'hold_ar' AS "route", 'overdue' AS "context"
FROM (SELECT "order_number", "invoice_id", "due", "amount" - "paid" AS "open_amount"
        FROM (SELECT "t0"."order_number", "t0"."customer", "t0"."channel", "t0"."fulfilling_warehouse", "t0"."value", "t0"."placed_date", "t0"."state", "invoice"."invoice_id", "invoice"."order_number" AS "order_number0", "invoice"."issued", "invoice"."due", "invoice"."amount", "invoice"."paid", "invoice"."status"
                FROM (SELECT "order_number", "customer", "channel", "fulfilling_warehouse", "value", "placed_date", "state"
                        FROM "order"
                        WHERE "state" IN ('held', 'placed')) AS "t0"
                    INNER JOIN "invoice" ON "t0"."customer" = "invoice"."customer") AS "t1"
        WHERE "t1"."status" = 'open' AND "t1"."due" < :as_of) AS "t3"
    INNER JOIN (SELECT "order_number"
        FROM (SELECT "t29"."order_number", "t29"."customer", "t29"."channel", "t29"."fulfilling_warehouse", "t29"."value", "t29"."placed_date", "t29"."state", COALESCE("t29"."n_short", 0) AS "n_short", COALESCE("t29"."n_price", 0) AS "n_price", COALESCE("t35"."n_due", 0) AS "n_due"
                FROM (SELECT "t17"."order_number", "t17"."customer", "t17"."channel", "t17"."fulfilling_warehouse", "t17"."value", "t17"."placed_date", "t17"."state", "t17"."n_short", "t28"."n_price"
                        FROM (SELECT "t5"."order_number", "t5"."customer", "t5"."channel", "t5"."fulfilling_warehouse", "t5"."value", "t5"."placed_date", "t5"."state", "t16"."n_short"
                                FROM (SELECT "order_number", "customer", "channel", "fulfilling_warehouse", "value", "placed_date", "state"
                                        FROM "order"
                                        WHERE "state" IN ('held', 'placed')) AS "t5"
                                    LEFT JOIN (SELECT "order_number", COUNT("line_no") AS "n_short"
                                        FROM (SELECT "t11"."order_number", "t11"."customer", "t11"."channel", "t11"."fulfilling_warehouse", "t11"."value", "t11"."placed_date", "t11"."state", "t11"."line_no", "t11"."item", "t11"."quantity", "t11"."unit_price", "t11"."ext_sales_price", "t11"."warehouse", "t11"."sold_date", "t11"."customer0", "t11"."channel0", "t11"."as_of_date", "t11"."quantity_on_hand", "t12"."warehouse" AS "warehouse0", "t12"."from_date", "t12"."to_date", "t12"."reason", COALESCE("t11"."quantity_on_hand", 0) AS "on_hand", "t12"."warehouse" IS NOT NULL AS "outage"
                                                FROM (SELECT "t8"."order_number", "t8"."customer", "t8"."channel", "t8"."fulfilling_warehouse", "t8"."value", "t8"."placed_date", "t8"."state", "t8"."line_no", "t8"."item", "t8"."quantity", "t8"."unit_price", "t8"."ext_sales_price", "t8"."warehouse", "t8"."sold_date", "t8"."customer0", "t8"."channel0", "t10"."as_of_date", "t10"."quantity_on_hand"
                                                        FROM (SELECT "t7"."order_number", "t7"."customer", "t7"."channel", "t7"."fulfilling_warehouse", "t7"."value", "t7"."placed_date", "t7"."state", "sales_line"."line_no", "sales_line"."item", "sales_line"."quantity", "sales_line"."unit_price", "sales_line"."ext_sales_price", "sales_line"."warehouse", "sales_line"."sold_date", "sales_line"."customer" AS "customer0", "sales_line"."channel" AS "channel0"
                                                                FROM (SELECT "order_number", "customer", "channel", "fulfilling_warehouse", "value", "placed_date", "state"
                                                                        FROM "order"
                                                                        WHERE "state" IN ('held', 'placed')) AS "t7"
                                                                    INNER JOIN "sales_line" ON "t7"."order_number" = "sales_line"."order_number") AS "t8"
                                                            LEFT JOIN (SELECT "inventory"."as_of_date", "inventory"."item", "inventory"."warehouse", "inventory"."quantity_on_hand"
                                                                FROM "inventory"
                                                                    INNER JOIN (SELECT "item", "warehouse", MAX("as_of_date") AS "_ttrp_latest_n8"
                                                                        FROM "inventory"
                                                                        GROUP BY "item", "warehouse") AS "t9" ON "inventory"."item" = "t9"."item" AND "inventory"."warehouse" = "t9"."warehouse" AND "inventory"."as_of_date" = "t9"."_ttrp_latest_n8") AS "t10" ON "t8"."item" = "t10"."item" AND "t8"."warehouse" = "t10"."warehouse") AS "t11"
                                                    LEFT JOIN (SELECT *
                                                        FROM "warehouse_outage"
                                                        WHERE "from_date" <= :as_of AND "to_date" >= :as_of) AS "t12" ON "t11"."warehouse" = "t12"."warehouse") AS "t13"
                                        WHERE "t13"."outage" OR "t13"."on_hand" < "t13"."quantity"
                                        GROUP BY "order_number") AS "t16" ON "t5"."order_number" = "t16"."order_number") AS "t17"
                            LEFT JOIN (SELECT "order_number", COUNT("line_no") AS "n_price"
                                FROM (SELECT "t20"."order_number", "t20"."line_no", "t20"."item", "t20"."unit_price", "t20"."customer", "t20"."channel", "t20"."placed_date", "t24"."price"
                                        FROM (SELECT "t19"."order_number", "sales_line0"."line_no", "sales_line0"."item", "sales_line0"."unit_price", "t19"."customer", "t19"."channel", "t19"."placed_date"
                                                FROM (SELECT "order_number", "customer", "channel", "fulfilling_warehouse", "value", "placed_date", "state"
                                                        FROM "order"
                                                        WHERE "state" IN ('held', 'placed')) AS "t19"
                                                    INNER JOIN "sales_line" AS "sales_line0" ON "t19"."order_number" = "sales_line0"."order_number") AS "t20"
                                            INNER JOIN (SELECT "t23"."order_number", "t23"."line_no", COALESCE("customer_price"."price", "price_list"."price") AS "price"
                                                FROM (SELECT "t22"."order_number", "sales_line1"."line_no", "sales_line1"."item", "sales_line1"."unit_price", "t22"."customer", "t22"."channel", "t22"."placed_date"
                                                        FROM (SELECT "order_number", "customer", "channel", "fulfilling_warehouse", "value", "placed_date", "state"
                                                                FROM "order"
                                                                WHERE "state" IN ('held', 'placed')) AS "t22"
                                                            INNER JOIN "sales_line" AS "sales_line1" ON "t22"."order_number" = "sales_line1"."order_number") AS "t23"
                                                    LEFT JOIN "customer_price" ON "t23"."item" = "customer_price"."item" AND "t23"."customer" = "customer_price"."customer" AND "t23"."placed_date" >= "customer_price"."valid_from" AND ("customer_price"."valid_to" IS NULL OR "t23"."placed_date" <= "customer_price"."valid_to")
                                                    LEFT JOIN "price_list" ON "t23"."item" = "price_list"."item" AND "t23"."channel" = "price_list"."channel" AND "t23"."placed_date" >= "price_list"."valid_from" AND ("price_list"."valid_to" IS NULL OR "t23"."placed_date" <= "price_list"."valid_to")) AS "t24" ON "t20"."order_number" = "t24"."order_number" AND "t20"."line_no" = "t24"."line_no") AS "t25"
                                WHERE "t25"."price" IS NULL OR ABS("t25"."unit_price" - "t25"."price") > :tolerance
                                GROUP BY "order_number") AS "t28" ON "t17"."order_number" = "t28"."order_number") AS "t29"
                    LEFT JOIN (SELECT "order_number", COUNT("invoice_id") AS "n_due"
                        FROM (SELECT "t31"."order_number", "t31"."customer", "t31"."channel", "t31"."fulfilling_warehouse", "t31"."value", "t31"."placed_date", "t31"."state", "invoice0"."invoice_id", "invoice0"."order_number" AS "order_number0", "invoice0"."issued", "invoice0"."due", "invoice0"."amount", "invoice0"."paid", "invoice0"."status"
                                FROM (SELECT "order_number", "customer", "channel", "fulfilling_warehouse", "value", "placed_date", "state"
                                        FROM "order"
                                        WHERE "state" IN ('held', 'placed')) AS "t31"
                                    INNER JOIN "invoice" AS "invoice0" ON "t31"."customer" = "invoice0"."customer") AS "t32"
                        WHERE "t32"."status" = 'open' AND "t32"."due" < :as_of
                        GROUP BY "order_number") AS "t35" ON "t29"."order_number" = "t35"."order_number") AS "t36"
        WHERE "t36"."n_due" > 0
        GROUP BY "order_number") AS "t39" ON "t3"."order_number" = "t39"."order_number"
